do $$ begin if current_setting('server_version_num')::integer<150000 then raise exception 'PostgreSQL 15+ obrigatório';end if;if to_regclass('public.erp_sales') is null or to_regclass('public.erp_purchase_orders') is null or to_regclass('public.erp_parties') is null then raise exception 'M05-M07 ausente';end if;if to_regclass('public.erp_financial_entries') is not null then raise exception 'Objetos M08 já existem sem histórico 0024';end if;if exists(select 1 from public.erp_permissions where key in('finance.read','finance.entry','finance.settle','finance.reverse','finance.adjust','treasury.read','treasury.manage','treasury.transfer','banking.read','banking.import','banking.reconcile','receivables.read','receivables.manage','payables.read','payables.manage') and category not in('Financeiro','Tesouraria','Bancário','Recebíveis','Pagamentos')) then raise exception 'Colisão de permissões M08';end if;end $$;
select now() checked_at,'M08_PREFLIGHT_OK' result;
